{
  "tools": [
    {
      "name": "add_component",
      "title": "Add Component",
      "toolset": "scene",
      "description": "Add a component to a game object, optionally setting its properties in the same call. The user can undo this. Returns the component's id.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          },
          "type": {
            "type": "string",
            "description": "The component type name, e.g. 'ModelRenderer'. get_component_type documents what exists."
          },
          "properties": {
            "type": "object",
            "description": "Optional json object of property values, e.g. {\"LightColor\": \"1,0.8,0.6,1\", \"Radius\": 512}."
          }
        },
        "required": [
          "id",
          "type"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "GameObject": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "delete_game_object",
      "title": "Delete Game Object",
      "toolset": "scene",
      "description": "Delete a game object and its children. The user can undo this.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          }
        },
        "required": [
          "id"
        ]
      }
    },
    {
      "name": "find_game_objects",
      "title": "Find Game Objects",
      "toolset": "scene",
      "description": "Search a scene's game objects by name substring, component type and/or tag. All filters are optional and combine - empty filters list everything. Returns each match with its hierarchy path and id.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Case insensitive substring of the object's name."
          },
          "component": {
            "type": "string",
            "description": "Case insensitive substring of a component type name the object must have."
          },
          "tag": {
            "type": "string",
            "description": "A tag the object must have."
          },
          "scene": {
            "type": "string",
            "description": "Scene name or resource path from list_scenes. Empty for the active scene."
          },
          "limit": {
            "type": "integer",
            "description": "How many matches to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 100
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer",
            "description": "How many matched in total, beyond what's shown."
          },
          "Results": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Name": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Path": {
                  "type": "string",
                  "description": "The object's place in the hierarchy, like 'Map/Props/Barrel'."
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Components": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              },
              "required": []
            }
          },
          "Truncated": {
            "type": "boolean",
            "description": "True when the scene was too big to finish searching."
          }
        },
        "required": []
      }
    },
    {
      "name": "get_game_object",
      "title": "Get Game Object",
      "toolset": "scene",
      "description": "Everything about one game object - enabled state, tags, world transform, parent, children, and its components. Set includeComponentProperties to also get every component's serialized properties.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          },
          "includeComponentProperties": {
            "type": "boolean",
            "description": "Include the full serialized properties of every component, not just their types.",
            "default": false
          }
        },
        "required": [
          "id"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Scene": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "Id": {
            "type": "string"
          },
          "Enabled": {
            "type": "boolean"
          },
          "ActiveInHierarchy": {
            "type": "boolean"
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "Parent": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              }
            },
            "required": [],
            "description": "The parent. Null when parented to the scene root."
          },
          "WorldPosition": {
            "type": "string"
          },
          "WorldRotation": {
            "type": "string"
          },
          "WorldScale": {
            "type": "string"
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Type": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Properties": {
                  "description": "The serialized properties. Null unless includeComponentProperties was set."
                }
              },
              "required": []
            }
          },
          "Children": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "set_game_object",
      "title": "Set Game Object",
      "toolset": "scene",
      "description": "Change a game object - rename, enable/disable, reparent, move, rotate or scale. Only the arguments you give change; everything else stays. The user can undo this.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          },
          "name": {
            "type": "string",
            "description": "New name."
          },
          "enabled": {
            "type": "boolean",
            "description": "Enable or disable the object."
          },
          "parent": {
            "type": "string",
            "description": "New parent game object id, or 'root' for the scene root."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "scale": {
            "type": "string",
            "description": "Scale as 'x,y,z', or a single number for uniform."
          }
        },
        "required": [
          "id"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "Enabled": {
            "type": "boolean"
          },
          "Parent": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              }
            },
            "required": [],
            "description": "The parent. Null when parented to the scene root."
          },
          "Position": {
            "type": "string"
          },
          "Angles": {
            "type": "string"
          },
          "Scale": {
            "type": "string"
          }
        },
        "required": []
      }
    }
  ],
  "total": 128
}
